```dart
/// Boots [_confluenceSyncPool] when [reader] has Confluence credentials;
/// a boot failure is reported through [onError] and the command proceeds
/// with the documented inline sequential fallback. Returns the booted
/// pool (or the unbooted shared pool on failure) — the same degradation
/// contract as the engine pool's lazy boot (gh-241).
Future<void> bootConfluenceSyncPool(
  PropertyReader reader, {
  SyncWorkerPool? pool,
  required void Function(String line) onError,
}) async {
  if (!confluenceSyncConfigured(reader)) return;
  try {
    await (pool ?? confluenceSyncWorkerPool).boot();
  } catch (e) {
    onError('dmtools: Confluence worker pool boot failed '
        '(confluence tools run sequentially): $e');
  }
```

