Future<int> _runProbeJob() {
  final script = File('${_tmp.path}/conf_pool_probe.js')
    ..writeAsStringSync('function action(params) { return "ok"; }');
  final config = File('${_tmp.path}/conf_pool_job.json')
    ..writeAsStringSync(jsonEncode({
