/// the Java IOException). Required for granular/scoped tokens.
SyncHttpResponse _titleAndSpaceResponse(
  _Conf config,
  String title,
  String space,
) {
  if (_isApiV2(config)) {
    final url = StringBuffer('${_baseUrlV2(config)}/pages?title='
        '${Uri.encodeQueryComponent(title)}');
