  }

  /// All values of a repeatable option flag (e.g. `--include`), in order.
  List<String> _optionValues(List<String> args, String flag) {
    final values = <String>[];
    for (var i = 0; i < args.length - 1; i++) {
      if (args[i] == flag) values.add(args[i + 1]);
    }
    return values;
  }

