  @override
  String? userProfile(String accountId) {
    final resp = SyncHttpClient.get(
      '${_config.baseUrl}/user?accountId='
      '${Uri.encodeQueryComponent(accountId)}',
      headers: _config.headers,
    );
    return resp.isOk ? resp.body : null;
  }
}

